#!/usr/bin/env bash
# run-kiosk.sh — the command a systemd user unit runs. Start it directly only for debugging.
#
# run-test.sh refuses to start without a seat because it is meant to be typed on the panel; this
# script is started by systemd, which owns the seat once linger is on, and it must not print to a
# terminal nobody is looking at.
#
# NTF_COMPOSITOR selects the Wayland compositor:
#   labwc (default) — a stacking compositor, so an external app can sit *inside* the frame the
#                     kiosk draws. Window rules generated by gen-labwc-config.sh pin every other
#                     window to the band between the bar and the dock.
#   cage            — the original single-window compositor. It cannot show two windows at once, so
#                     external apps cover the whole panel. Kept as a rollback path: if labwc ever
#                     fails to start, the panel stays usable with NTF_COMPOSITOR=cage.
set -uo pipefail

APPDIR="${APPDIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
ELECTRON="${ELECTRON:-$(cd "$APPDIR/.." && pwd)/electron-dist/electron}"
ENTRY="$APPDIR/dist/main/main.js"
LOG="${NTF_LOG:-/tmp/ntf-run.log}"
COMPOSITOR="${NTF_COMPOSITOR:-labwc}"

[ -x "$ELECTRON" ] || { echo "thiếu Electron: $ELECTRON" >&2; exit 1; }
[ -f "$ENTRY" ] || { echo "chưa build: $ENTRY" >&2; exit 1; }
[ "$(id -u)" -ne 0 ] || { echo "không chạy bằng root" >&2; exit 1; }

export XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
export LIBSEAT_BACKEND="${LIBSEAT_BACKEND:-seatd}"
export XDG_SESSION_TYPE=wayland
unset DISPLAY

# VA-API driver selection. Empty by default on purpose: naming a driver that is not installed makes
# libva fail outright, which is worse than the present "no hardware decoder". Set
# NTF_VAAPI_DRIVER=nvidia only after `vainfo` already lists profiles for it, then this also turns on
# Chromium's VaapiOnNvidiaGPUs feature — without that feature vaapi_wrapper skips an `nvidia-drm`
# render node and never creates a decoder.
if [ -n "${NTF_VAAPI_DRIVER:-}" ]; then
  export LIBVA_DRIVER_NAME="$NTF_VAAPI_DRIVER"
  if [ "$NTF_VAAPI_DRIVER" = "nvidia" ]; then
    # The EGL backend of nvidia-vaapi-driver regressed in driver 525+; `direct` is the working path.
    export NVD_BACKEND="${NVD_BACKEND:-direct}"
    export NTF_GPU_NVIDIA=1
  fi
fi

# Keep the log from growing without bound on a box that runs for weeks.
if [ -f "$LOG" ] && [ "$(stat -c%s "$LOG")" -gt 5242880 ]; then
  mv -f "$LOG" "$LOG.1"
fi

{
  echo "=== $(date -Is) khởi động kiosk (compositor=$COMPOSITOR) ==="
} >>"$LOG"

# NTF_ELECTRON_ARGS exists so an operator can add --remote-debugging-port=9222 when diagnosing
# without editing this file; the default unit starts with no debugging port exposed.
# shellcheck disable=SC2086
ELECTRON_CMD=("$ELECTRON" "$ENTRY" ${NTF_ELECTRON_ARGS:-})

if [ "$COMPOSITOR" = "labwc" ]; then
  if ! command -v labwc >/dev/null 2>&1; then
    echo "thiếu labwc — quay lại cage" >>"$LOG"
    COMPOSITOR=cage
  else
    CONFIG_DIR="${NTF_LABWC_DIR:-$HOME/.config/labwc}"
    # Regenerated on every start so the band always matches the mode the panel actually reports.
    # A stale rc.xml would silently clip external windows to the wrong rectangle.
    if ! bash "$APPDIR/scripts/gen-labwc-config.sh" >>"$LOG" 2>&1; then
      echo "sinh cấu hình labwc thất bại — quay lại cage" >>"$LOG"
      COMPOSITOR=cage
    fi
  fi
fi

if [ "$COMPOSITOR" = "labwc" ]; then
  # labwc -S parses its argument as a shell word list, so anything with spaces in a path would be
  # split. Handing it a script path avoids that entirely, and makes the kiosk the session leader:
  # when Electron exits, labwc exits, and systemd sees the unit stop.
  SESSION="$CONFIG_DIR/session.sh"
  {
    printf '#!/usr/bin/env bash\n'
    printf 'exec'
    printf ' %q' "${ELECTRON_CMD[@]}"
    printf '\n'
  } >"$SESSION" || { echo "không ghi được $SESSION" >&2; exit 1; }
  chmod +x "$SESSION"

  # exec so systemd tracks labwc itself; killing the unit then stops the whole tree, and the kiosk
  # inherits the same seat and DRM device Cage used.
  exec labwc -C "$CONFIG_DIR" -S "$SESSION" >>"$LOG" 2>&1
fi

# cage path — unchanged from before labwc, kept verbatim so a rollback needs no rebuild.
exec cage -d -s -- "${ELECTRON_CMD[@]}" >>"$LOG" 2>&1